  /* A word means a different thing in a different subject. Checked first. */
  var SUBJECT_RULES = {
    cs: [['chip', 4, 'memory ram'], ['code', 4, 'function'], ['search', 4, 'binary search'], ['list', 4, 'array list']],
    math: [['function', 4, 'function graph'], ['equals', 4, 'solve solving both sides']],
    economics: [['up', 3, 'supply curve'], ['coins', 4, 'price']]
  };

  function compile(list) {
    var out = [], i, j;
    for (i = 0; i < list.length; i++) {
      var words = list[i][2].split(/\s+/), alts = [];
      for (j = 0; j < words.length; j++) {
        var w = words[j];
        if (!w) continue;
        var stem = w.charAt(w.length - 1) === '*';
        w = (stem ? w.slice(0, -1) : w).replace(/[.?+()[\]{}|\\^$]/g, '\\$&').replace(/\s+/g, '\\s+').replace(/-/g, '[- ]?');
        alts.push(stem ? w + '[a-z]*' : w + '(?:s|es)?');
      }
      out.push({ icon: list[i][0], pri: list[i][1], re: new RegExp('(?:^|[^a-z])(' + alts.join('|') + ')(?![a-z])', 'i') });
    }
    return out;
  }
  var COMPILED = compile(RULES), BY_SUBJECT = {}, k;
  for (k in SUBJECT_RULES) if (SUBJECT_RULES.hasOwnProperty(k)) BY_SUBJECT[k] = compile(SUBJECT_RULES[k]);

  function has(name) {
    return Object.prototype.hasOwnProperty.call(P, name) || Object.prototype.hasOwnProperty.call(S, name);
  }
  function names() {
    var out = [], n;
    for (n in P) if (P.hasOwnProperty(n)) out.push(n);
    for (n in S) if (S.hasOwnProperty(n)) out.push(n);
    return out.sort();
  }

  /* Every candidate for one label, best first. */
  function candidates(text, subject) {
    var t = ' ' + String(text == null ? '' : text).toLowerCase() + ' ', out = [], seen = {}, i, m;
    var lists = [BY_SUBJECT[subject] || [], COMPILED];
    for (var L = 0; L < lists.length; L++) {
      for (i = 0; i < lists[L].length; i++) {
        var r = lists[L][i];
        m = r.re.exec(t);
        if (!m) continue;
        var at = m.index + m[0].length - m[1].length;
        if (seen[r.icon] && seen[r.icon].pri >= r.pri) continue;
        seen[r.icon] = { icon: r.icon, pri: r.pri, at: at };
      }
    }
    for (var n in seen) if (seen.hasOwnProperty(n)) out.push(seen[n]);
    out.sort(function (a, b) { return (b.pri - a.pri) || (a.at - b.at); });
    return out;
  }
  function match(text, subject) {
    var c = candidates(text, subject);
    return c.length ? c[0].icon : '';
  }
  /* One icon per label. A second label that would repeat an icon takes its
     own next-best match when it has one as strong; otherwise it repeats - two
     steps about the heart both being the heart is true. */
  function pick(labels, subject) {
    var out = [], used = {}, i, j;
    for (i = 0; i < labels.length; i++) {
      var c = candidates(labels[i], subject), choice = c.length ? c[0] : null;
      if (choice && used[choice.icon]) {
        for (j = 1; j < c.length; j++) {
          if (!used[c[j].icon] && c[j].pri >= choice.pri - 1 && c[j].pri >= 2) { choice = c[j]; break; }
        }
      }
      out.push(choice ? choice.icon : '');
      if (choice) used[choice.icon] = 1;
    }
    return out;
  }

