    atom: 'atom', microscope: 'microscope', magnet: 'magnet', battery: 'battery', 'light bulb': 'bulb',
    lightbulb: 'bulb', globe: 'globe', earth: 'globe', planet: 'planet', rocket: 'rocket', heart: 'heart',
    brain: 'brain', eye: 'eye', ear: 'ear', bone: 'bone', skeleton: 'bone', tooth: 'tooth', teeth: 'tooth',
